package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaIdDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_sami" to DuaText("Berlindung dari Kejahatan Indraku", "Ya Allah, aku berlindung kepada-Mu dari kejahatan pendengaranku, kejahatan penglihatanku, kejahatan lidahku, kejahatan hatiku, dan kejahatan hawa nafsuku.", "Diajarkan kepada Shakal bin Humayd (RA).", "Doa untuk melindungi anggota tubuh dan diri dari dosa."),
        "dua_hadm_gharaq" to DuaText("Perlindungan dari Kematian Mendadak dan Kecelakaan", "Ya Allah, aku berlindung kepada-Mu dari tertimpa (bangunan), dari jatuh dari ketinggian, dari tenggelam, terbakar, dan usia tua; dari setan yang menyesatkanku di saat kematian, dari kematian karena melarikan diri dari jalan-Mu, dan dari kematian karena sengatan (yang berbisa).", "Perlindungan dari kecelakaan dan kematian yang buruk.", "Doa perlindungan dari Nabi ﷺ."),
        "dua_ju_khiyanah" to DuaText("Perlindungan dari Kelaparan dan Pengkhianatan", "Ya Allah, aku berlindung kepada-Mu dari rasa lapar, karena ia adalah teman yang jahat, dan aku berlindung kepada-Mu dari pengkhianatan, karena ia adalah teman curhat yang jahat.", "Berlindung dari kelaparan dan pengkhianatan.", "Doa perlindungan dari Nabi ﷺ."),
        "dua_huda_tuqa" to DuaText("Bimbingan, Kesalehan, Kesucian dan Kecukupan", "Ya Allah, aku mohon kepada-Mu petunjuk, ketakwaan, kesucian, dan kemandirian.", "Doa Nabi yang singkat dan komprehensif ﷺ.", "Empat keberkahan mendasar agama dan dunia ini."),
        "dua_aslih_li_dini" to DuaText("Perbaiki Agamaku Dunia dan Akhirat", "Ya Allah, luruskanlah agamaku, yang menjadi penjaga segala urusanku; perbaikilah kehidupan duniawiku yang menjadi penghidupanku; dan perbaiki akhiratku, ke sanalah aku akan kembali. Jadikanlah hidup sebagai tambahan bagiku dalam segala kebaikan, dan jadikan kematian sebagai keringanan bagiku dari segala keburukan.", "Mereformasi agama, dunia dan akhirat – ketiganya.", "Doa komprehensif Nabi ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Arahkan Hati Kami pada Ketaatan Anda", "Ya Allah Pembalik hati, arahkan hati kami kepada ketaatan-Mu.", "Doa agar hati tetap teguh dalam ketaatan.", "Hati seluruh manusia berada di antara dua jari Yang Maha Penyayang."),
        "dua_jannah_nar" to DuaText("Meminta Jannah, Perlindungan dari Api", "Ya Allah, aku memohon kepada-Mu surga dan aku berlindung kepada-Mu dari api neraka.", "Setelah tashahhud atau sewaktu-waktu.", "Nabi ﷺ bersabda: doa kami juga berkisar pada hal ini."),
        "dua_khayri_kullih" to DuaText("Semuanya Baik, Sekarang dan Nanti", "Ya Allah, aku memohon kepada-Mu segala kebaikan, baik yang langsung maupun yang tertunda, yang aku ketahui dan yang tidak aku ketahui, dan aku berlindung kepada-Mu dari segala keburukan, baik yang langsung maupun yang tertunda, yang aku ketahui dan yang tidak aku ketahui. Ya Allah, aku memohon kepada-Mu surga, dan ucapan serta amal apa pun yang mendekatkanku padanya, dan aku berlindung kepada-Mu dari api neraka, dan dari ucapan dan amal apa pun yang mendekatkanku padanya.", "Nabi ﷺ mengajarkan doa komprehensif ini kepada Aisha (RA) (bagian dari doa).", "Sebuah doa yang mengumpulkan setiap kebaikan."),
        "dua_ihdini_saddidni" to DuaText("Bimbing Aku dan Jaga Aku Tetap Tegak", "Ya Allah, bimbinglah aku dan jagalah aku di jalan yang benar.", "Nabi ﷺ mengajarkannya kepada Ali (RA).", "Anggaplah bimbingan sebagai petunjuk sepanjang jalan, dan sadad sebagai lurusnya anak panah."),
        "dua_hubbaka" to DuaText("Meminta Cinta Allah", "Ya Allah, aku memohon kepada-Mu cinta-Mu, cinta orang-orang yang mencintai-Mu, dan amal yang membawaku kepada cinta-Mu. Ya Allah, jadikanlah cinta-Mu lebih berharga bagiku daripada diriku sendiri, keluargaku, dan air dingin.", "Doa Dawud (AS) yang diriwayatkan Nabi ﷺ.", "Cinta kepada Allah adalah kekayaan terbesar."),
        "dua_filal_khayrat" to DuaText("Berbuat Baik dan Meninggalkan Kejahatan", "Ya Allah, aku mohon kepada-Mu agar aku bisa beramal shaleh, meninggalkan keburukan, dan mencintai orang-orang miskin, serta mengampuni dan mengasihaniku. Dan apabila Engkau menghendaki suatu cobaan bagi suatu kaum, ambillah aku tanpa diadili. Aku memohon kepada-Mu cinta-Mu, cinta orang-orang yang mencintai-Mu, dan cinta amal yang mendekatkanku pada cinta-Mu.", "Allah mengajarkan doa ini kepada Nabi ﷺ dalam mimpi.", "Nabi ﷺ bersabda: benar, maka pelajari dan ajarkan."),
        "dua_bi_ilmikal_ghayb" to DuaText("Biarkan Aku Hidup Selagi Hidup Baik", "Ya Allah, dengan ilmu-Mu yang gaib dan kekuasaan-Mu atas ciptaan, jagalah aku tetap hidup selama Engkau mengetahui bahwa hidup ini lebih baik bagiku, dan ambillah aku ketika Engkau tahu kematian lebih baik bagiku. Ya Allah, aku memohon kepada-Mu untuk bertakwa kepada-Mu baik secara pribadi maupun di depan umum, tentang kebenaran dalam rasa senang dan marah, dan tentang sikap bersahaja dalam kemiskinan dan kekayaan.", "Doa Ammar bin Yasir (RA) (bagian pembuka).", "Nabi ﷺ mengucapkan doa ini dalam doa."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: Al-Mannan", "Ya Allah, aku mohon kepada-Mu, karena hanya milik-Mu segala puji; tidak ada tuhan selain Engkau, Yang Maha Pemberi nikmat, Yang Maha Pencipta langit dan bumi. Wahai Pemilik Keagungan dan Kehormatan, Wahai Yang Hidup Abadi, Wahai Pemelihara!", "Nabi ﷺ mengatakan orang ini berdoa dengan Nama Allah Yang Maha Besar.", "Doa yang dibuat dengan Nama ini terkabul."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: Al-Ahad As-Samad", "Ya Allah, aku memohon kepada-Mu, karena aku bersaksi bahwa Engkaulah Allah; tidak ada tuhan selain Engkau, Yang Maha Esa, Yang Maha Esa, yang tidak melahirkan dan tidak dilahirkan, dan tidak ada yang sebanding dengan-Nya.", "Nabi ﷺ bersabda orang ini bertanya kepada Allah dengan Nama Yang Maha Besar.", "Ketika diminta olehnya, Dia memberi; ketika dipanggil olehnya, Dia menjawab."),
        "dua_thabbitni_hadiyan" to DuaText("Jadikan Aku Teguh, Terbimbing dan Menjadi Pembimbing", "Ya Allah, jadikanlah aku teguh, dan jadikan aku orang yang memberi petunjuk dan mendapat petunjuk.", "Nabi ﷺ membuat doa ini untuk Jarir (RA) (untuk dirimu sendiri ucapkan 'thabbitni').", "Doa asli Jarir (RA) menggunakan kata 'thabbit-hu'."),
        "dua_rabbighfir_tub_alayya" to DuaText("Maafkan Saya dan Terimalah Pertobatan Saya", "Ya Tuhanku, maafkan aku dan terimalah taubatku. Sesungguhnya Engkau Maha Penerima taubat lagi Maha Penyayang.", "Seratus kali dalam sekali duduk — Amalan Nabi ﷺ.", "Para sahabat menghitung Nabi ﷺ mengucapkannya seratus kali dalam sekali duduk."),
        "dua_rafiq_ala" to DuaText("Doa Orang yang Sekarat", "Ya Allah, maafkan aku, kasihanilah aku dan satukan aku dengan Sahabat Tertinggi.", "Doa terakhir Nabi ﷺ — untuk diucapkan sendiri oleh orang sakit.", "Nabi ﷺ mengucapkan doa ini pada saat wafatnya."),
        "dua_la_bas_tahur" to DuaText("Menghibur Orang Sakit: Pemurnian", "Tidak ada salahnya; itu adalah penyucian (dari dosa), jika Allah menghendaki.", "Untuk menghibur orang sakit saat menjenguk.", "Nabi ﷺ mengatakan hal ini ketika menjenguk orang sakit."),
        "dua_talqeen" to DuaText("Talqeen untuk Orang yang Sekarat", "Tidak ada yang berhak disembah kecuali Allah.", "Bacalah kalimah di dekat orang yang sekarat (jangan memaksa mereka untuk mengucapkannya).", "Barang siapa yang terakhir mengucapkan 'La ilaha illallah', maka dia akan masuk surga (Abu Dawud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("Daripada Menginginkan Kematian", "Ya Allah, hidupkan aku selama hidup ini lebih baik bagiku, dan ambillah aku ketika kematian lebih baik bagiku.", "Daripada mengharapkan kematian dalam kesulitan.", "Nabi ﷺ melarang mengharapkan kematian dan mengajarkan hal ini sebagai gantinya."),
        "dua_for_one_i_cursed" to DuaText("Untuk Seseorang yang Aku Sakiti dengan Kata-kata", "Ya Allah, setiap mukmin yang aku hina, jadikanlah itu sebagai sarana kedekatan kepada-Mu di hari kiamat.", "Untuk seseorang yang Anda ajak bicara buruk dalam keadaan marah.", "Doa Nabi ﷺ."),
        "dua_praising_someone" to DuaText("Saat Memuji Seseorang", "Aku menganggap si fulan itu seperti ini, dan Allah adalah Penghitungnya, dan aku tidak menjamin kesucian seseorang di hadapan Allah.", "Saat memuji seseorang, bukannya melebih-lebihkan.", "Nabi ﷺ mengajarkan etika memuji ini."),
        "dua_being_praised" to DuaText("Ketika Anda Dipuji", "Ya Allah, jangan perhitungkan aku atas apa yang mereka katakan, dan maafkan aku atas apa yang tidak mereka ketahui.", "Saat mendengar diri sendiri dipuji — praktik seorang Sahabat (RA).", "Cara menghindari kesombongan saat dipuji."),
        "dua_non_muslim_sneezes" to DuaText("Ketika Non-Muslim Bersin", "Semoga Allah membimbing Anda dan mengatur urusan Anda dengan benar.", "Ketika seorang non-Muslim bersin dan mengucapkan 'Alhamdulillah'.", "Orang-orang Yahudi akan bersin di dekat Nabi ﷺ berharap dia akan mengatakan 'Yarhamukallah', dan dia akan mengatakan ini."),
        "dua_reply_ahl_kitab_salam" to DuaText("Membalas Salam Ahli Kitab", "Dan padamu.", "Ketika Ahli Kitab menyapa dengan salam.", "Perintah Nabi ﷺ."),
        "dua_fasting_invited" to DuaText("Bila Diundang Saat Puasa", "Saya sedang puasa.", "Saat diajak berpuasa, atau saat ada yang bertengkar denganmu.", "Jika orang yang berpuasa menerima ajakan, hendaknya ia mendoakan tuan rumah."),
        "dua_for_who_gave_drink" to DuaText("Untuk Siapapun yang Memberiku Makan", "Ya Allah, berilah makan kepada orang yang memberiku makan, dan berikanlah minuman kepada orang yang memberiku minum.", "Untuk siapapun yang memberimu makanan atau minuman.", "Nabi ﷺ membuat doa ini untuk al-Miqdad (RA)."),
        "dua_eid_greeting" to DuaText("Ucapan Idul Fitri", "Semoga Allah menerima (amal shaleh) dari kami dan kalian.", "Satu sama lain di hari Idul Fitri — Amalan Para Sahabat Mulia (RA).", "Para sahabat mengatakan hal ini ketika mereka bertemu di hari raya Idul Fitri."),
        "dua_wedding_night" to DuaText("Untuk Mempelai Wanita Setelah Nikah", "Ya Allah, aku memohon kepada-Mu kebaikannya dan kebaikan alam yang Engkau ciptakan dengannya, dan aku berlindung kepada-Mu dari kejahatannya dan keburukan alam yang Engkau ciptakan dengannya.", "Seusai nikah, letakkan tangan di kening istri.", "Ajaran Nabi ﷺ — keberkahan dalam pernikahan."),
        "dua_istisqa_ibadak" to DuaText("Sirami Pelayan dan Hewan Anda", "Ya Allah, berikanlah air kepada hamba-hamba-Mu dan hewan-hewan-Mu, sebarkan rahmat-Mu dan hidupkan tanah mati-Mu.", "Meminta hujan (istisqa).", "Nabi ﷺ mengucapkan doa ini agar turun hujan."),
        "dua_seeing_clouds" to DuaText("Melihat Awan Gelap", "Ya Allah, aku berlindung kepada-Mu dari kejahatannya.", "Saat melihat awan gelap di langit; jika hujan ucapkan 'Allahumma sayyiban nafi'a'.", "Saat melihat awan, Nabi ﷺ akan meninggalkan apa yang dia lakukan dan mengucapkan doa ini."),
        "dua_jamarat" to DuaText("Melempari Jamarat", "Allah Maha Besar.", "Dengan setiap kerikil yang dilempar.", "Nabi ﷺ mengucapkan takbir dengan setiap kerikil, kemudian setelah jamrah pertama dan kedua menghadap kiblat dan berdoa panjang."),
        "dua_rabbi_ainni" to DuaText("Ya Tuhanku, tolonglah aku dan jangan melawanku", "Ya Tuhanku, bantulah aku dan jangan bantu orang lain untuk melawanku, berilah aku kemenangan dan jangan berikan kemenangan kepada orang lain atasku, buatlah rencana untukku dan jangan buat rencana untuk melawanku, berilah aku petunjuk dan mudahkanlah petunjuk bagiku, dan bantulah aku terhadap orang yang menganiaya aku.", "Doa komprehensif Nabi ﷺ (bagian pembuka).", "Sebuah doa yang mengumpulkan setiap bantuan dalam agama dan dunia ini."),
        "dua_ati_nafsi_taqwaha" to DuaText("Berikan Jiwaku Taqwanya", "Ya Allah, berilah jiwaku ketakwaan dan sucikanlah jiwaku, karena Engkaulah yang paling baik mensucikannya. Anda adalah Penjaganya dan Tuannya.", "Untuk mereformasi dan memurnikan diri.", "Nabi ﷺ biasa mengucapkan doa ini."),
        "dua_iqsim_lana_khashyatik" to DuaText("Beri Kami Rasa Takut pada Anda", "Ya Allah, beri kami rasa takut yang cukup kepada-Mu untuk menghalangi kami dan kemaksiatan kepada-Mu, ketaatan yang cukup untuk membawa kami ke surga-Mu, dan keyakinan yang cukup untuk memudahkan kami menghadapi musibah di dunia. Biarkan kami menikmati pendengaran kami, penglihatan kami dan kekuatan kami selama Engkau menjaga kami tetap hidup, dan membuat mereka hidup lebih lama dari kami. Balas dendam kami kepada orang-orang yang menganiaya kami, bantulah kami melawan musuh-musuh kami, jangan biarkan musibah kami menimpa agama kami, jangan jadikan dunia ini perhatian terbesar kami atau batas pengetahuan kami, dan jangan jadikan kami orang-orang yang tidak mau memberi ampun kepada kami.", "Ketika bangun dari suatu pertemuan — Nabi ﷺ jarang sekali bangkit tanpa mengucapkan doa ini.", "Doa yang komprehensif untuk kebaikan agama, dunia dan akhirat."),
        "dua_infani_bima_allamtani" to DuaText("Manfaatkan Saya Dengan Apa yang Anda Ajarkan kepada Saya", "Ya Allah, berilah aku manfaat dengan apa yang telah Engkau ajarkan padaku, ajari aku apa yang bermanfaat bagiku, dan tambahlah ilmuku.", "Saat mencari ilmu atau sebelum belajar.", "Doa untuk ilmu yang bermanfaat dan mengamalkannya."),
        "dua_jar_su" to DuaText("Perlindungan dari Tetangga yang Buruk", "Ya Allah, aku berlindung kepada-Mu dari tetangga yang buruk di tempat tinggal tetap, karena tetangga itu sedang bepergian.", "Untuk perlindungan dari tetangga yang buruk.", "Nabi ﷺ memerintahkan mencari perlindungan dari hal ini."),
        "dua_ishfi_abdak" to DuaText("Untuk Kesembuhan Orang Sakit", "Ya Allah, sembuhkanlah hamba-Mu agar ia bisa menghadapi musuh demi Engkau atau bisa berjalan untuk shalat demi Engkau.", "Bagi orang sakit ketika menjenguknya.", "Nabi ﷺ mengajarkan perkataan ini kepada orang sakit."),
        "dua_la_mania" to DuaText("Tidak Ada Yang Dapat Menahan Apa yang Anda Berikan", "Tidak ada yang berhak disembah kecuali Allah, sendiri, tanpa sekutu. Milik-Nya kekuasaan dan milik-Nya pujian, dan Dia Mahakuasa atas segala sesuatu. Ya Allah, tidak ada seorang pun yang dapat menahan apa yang Engkau berikan, dan tidak ada seorang pun yang dapat memberikan apa yang Engkau tahan, dan harta orang kaya tidak ada gunanya melawan Engkau.", "Setelah salam salat wajib.", "Nabi ﷺ mengatakan hal ini setelah setiap shalat wajib."),
        "dua_slaughtering" to DuaText("Saat Menyembelih Hewan", "Dengan menyebut nama Allah, dan Allah Maha Besar.", "Saat menyembelih atau menyembelih hewan.", "Nabi ﷺ mengucapkan Bismillah dan takbir pada saat kurban."),
    )
}
